def todo_write(todos: list[dict], session_id: str = '', **kwargs) -> dict:
    """整体替换当前任务列表。

    模型每次调用必须发送完整列表（非增量更新）。
    用于在执行多步骤任务时向用户展示实时进度。

    参数:
        todos: 完整任务列表，每项包含:
            - content (str): 任务描述（非空，去重）
            - status (str): pending | in_progress | completed
        session_id: 会话 ID（可选，用于隔离不同会话的任务列表）

    返回:
        dict: 包含验证后的列表和统计计数
    """
    key = session_id or '_default'

    if not isinstance(todos, list):
        return {'success': False, 'error': 'todos 必须是数组'}

    # 校验 + 去重 + 清洗
    validated = []
    seen_contents = set()
    active_count = 0

    for item in todos:
        if not isinstance(item, dict):
            return {'success': False, 'error': '每个 todo 项必须是对象'}

        content = (item.get('content') or '').strip()
        status = (item.get('status') or '').strip()

        # 校验 content
        if not content:
            return {'success': False, 'error': 'todo 的 content 不能为空'}

        # 校验去重
        if content in seen_contents:
            return {'success': False,
                    'error': 'todo 内容重复: %s' % content}
        seen_contents.add(content)

        # 校验 status
        if status not in _VALID_STATUSES:
            return {'success': False,
                    'error': '无效状态: %s（允许: pending, in_progress, completed）' % status}

        if status == 'in_progress':
            active_count += 1

        validated.append({'content': content, 'status': status})

    # 存储
    _todos[key] = validated

    # 统计
    counts = {
        'pending': sum(1 for t in validated if t['status'] == 'pending'),
        'in_progress': sum(1 for t in validated if t['status'] == 'in_progress'),
        'completed': sum(1 for t in validated if t['status'] == 'completed'),
    }

    logger.info('任务列表已更新: session=%s total=%d pending=%d active=%d done=%d',
                key, len(validated), counts['pending'],
                counts['in_progress'], counts['completed'])

    return {
        'success': True,
        'todos': validated,
        'counts': counts,
    }


